// Branded Fried King receipt. Restaurant details come from the settings table so nothing is hardcoded.
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function rs(n){ return '₹' + Math.round(Number(n||0)).toLocaleString('en-IN'); }
var oRaw = $('Get Order').first().json; var o = Array.isArray(oRaw) ? (oRaw[0]||{}) : oRaw;
var S = {}; $('Get Settings').all().forEach(function(it){ var r = it.json; (Array.isArray(r)?r:[r]).forEach(function(x){ if (x && x.key) S[x.key] = x.value; }); });
var items = [];
if (Array.isArray(o.items_json) && o.items_json.length) {
  items = o.items_json.map(function(i){ return { name: i.name || i.item_name, qty: Number(i.quantity)||1, price: Number(i.price||i.unit_price)||0 }; });
} else {
  items = String(o.items||'').split(', ').filter(Boolean).map(function(s){ var m = s.match(/^(.*) x(\d+)/); return { name: m?m[1]:s, qty: m?Number(m[2]):1, price: 0 }; });
}
var LABEL = { delivery:'Delivery', takeaway:'Takeaway', 'dine-in':'Dine-in' };
var type = LABEL[o.order_type] || 'Order';
var w = new Date(new Date(o.created_at || Date.now()).getTime() + 5.5*3600*1000);
var M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var stamp = w.getUTCDate()+' '+M[w.getUTCMonth()]+' '+w.getUTCFullYear()+' · '+w.getUTCHours()+':'+String(w.getUTCMinutes()).padStart(2,'0');
var name = S.restaurant_name || 'Fried King';
var phone = S.phone || '+91 97421 75222';
var rows = items.map(function(i){ var lt = i.price*i.qty; return '<tr><td class="it">'+esc(i.name)+'</td><td class="q">x'+i.qty+'</td><td class="p">'+(lt>0?rs(lt):'')+'</td></tr>'; }).join('');
var paid = String(o.payment_status||'') === 'paid';
var css = '*{box-sizing:border-box}body{margin:0;padding:24px 16px;background:#1A1A1A;font-family:Poppins,sans-serif;color:#1C1C1C}'+
 '.card{background:#FFFFFF;border-radius:18px;overflow:hidden;max-width:420px;margin:0 auto}'+
 '.top{background:#D62300;color:#fff;text-align:center;padding:22px 16px 18px}.chk{height:18px;background:repeating-conic-gradient(#D62300 0% 25%, #FFFFFF 0% 50%) 0 0/18px 18px}.top img{height:64px;border-radius:50%;background:#fff;padding:4px;margin-bottom:8px}'+
 '.top h1{margin:0;font-size:30px;letter-spacing:4px;font-weight:800}.top .tag{font-size:11px;letter-spacing:2px;color:#FFFFFF;margin-top:4px}'+
 '.top .ad{font-size:11px;opacity:.9;margin-top:6px;line-height:1.6}.body{padding:18px 20px 22px}'+
 '.num{text-align:center;font-size:24px;font-weight:800;letter-spacing:2px}.when{text-align:center;font-size:11px;color:#7A7A7A;margin-top:3px}'+
 '.pill{display:block;width:max-content;margin:12px auto 0;background:#FFFFFF;color:#D62300;border:2px solid #D62300;border-radius:30px;padding:6px 16px;font-size:12px;font-weight:700;letter-spacing:1px}'+
 '.kv{display:flex;justify-content:space-between;font-size:12.5px;padding:3px 0}.kv span:first-child{color:#8A8A8A}.kv span:last-child{font-weight:600;text-align:right;max-width:65%}'+
 'hr{border:none;border-top:1.5px dashed #F2B8AE;margin:14px 0}table{width:100%;border-collapse:collapse}td{padding:7px 0;font-size:13px;border-bottom:1px dotted #F6D2CC}'+
 'td.it{font-weight:600}td.q{text-align:right;color:#8A8A8A;width:44px}td.p{text-align:right;font-weight:700;width:90px}'+
 '.total{margin-top:14px;background:#D62300;color:#fff;border-radius:12px;display:flex;justify-content:space-between;align-items:center;padding:13px 16px}'+
 '.total span{font-size:12px;letter-spacing:2px}.total b{font-size:24px}.foot{text-align:center;font-size:12px;color:#5A5A5A;margin-top:14px;line-height:1.7}.foot b{color:#D62300}';
var html = '<html><head><meta charset="utf-8"><style>'+css+'</style></head><body><div class="card"><div class="top">'+
 (S.logo_url ? '<img src="'+esc(S.logo_url)+'">' : '')+
 '<h1>'+esc(name.toUpperCase())+'</h1>'+(S.tagline?'<div class="tag">'+esc(S.tagline)+'</div>':'')+
 '<div class="ad">'+esc(S.address||'Arista Enclave, Ground Floor, 2nd Main Rd, Pandeshwar, Mangaluru, Karnataka 575001')+'<br>'+esc(phone)+'</div></div><div class="chk"></div><div class="body">'+
 '<div class="num">'+esc(o.order_number)+'</div><div class="when">'+esc(stamp)+'</div>'+
 '<span class="pill">'+esc(type.toUpperCase())+(o.table_number?' · TABLE '+esc(o.table_number):'')+' · '+(paid?'PAID':(o.order_type==='delivery'?'CASH ON DELIVERY':'PAY AT COUNTER'))+'</span><hr>'+
 '<div class="kv"><span>Name</span><span>'+esc(o.customer_name||'Guest')+'</span></div>'+
 '<div class="kv"><span>Phone</span><span>'+esc(o.customer_phone||'')+'</span></div>'+
 (o.order_type==='delivery' && o.address ? '<div class="kv"><span>Address</span><span>'+esc(o.address)+'</span></div>' : '')+
 '<hr><table>'+rows+'</table><div class="total"><span>TOTAL</span><b>'+rs(Math.round(o.total))+'</b></div>'+
 '<div class="foot">Thank you for ordering with <b>'+esc(name)+'</b>!<br>Questions? WhatsApp us on '+esc(phone)+'</div></div><div class="chk"></div></div></body></html>';
return [{ json: { html: html, google_fonts: 'Poppins:400,600,700,800', order_number: o.order_number } }];
